\\u0e40\\u0e1c\\u0e22\\u0e41\\u0e1e\\u0e23\\u0e48 \\u0e17\\u0e31\\u0e49\\u0e07\\u0e19\\u0e35\\u0e49\\u0e43\\u0e19\\u0e01\\u0e23\\u0e30\\u0e1a\\u0e27\\u0e19\\u0e01\\u0e32\\u0e23\\u0e08\\u0e30\\u0e44\\u0e21\\u0e48\\u0e21\\u0e35\\u0e01\\u0e32\\u0e23\\u0e40\\u0e1b\\u0e34\\u0e14\\u0e40\\u0e1c\\u0e22\\u0e02\\u0e49\\u0e2d\\u0e21\\u0e39\\u0e25\\u0e15\\u0e48\\u0e2d\\u0e01\\u0e31\\u0e19\\u0e23\\u0e30\\u0e2b\\u0e27\\u0e48\\u0e32\\u0e07\\u0e1c\\u0e39\\u0e49\\u0e1b\\u0e23\\u0e30\\u0e40\\u0e21\\u0e34\\u0e19\\u0e41\\u0e25\\u0e30\\u0e1c\\u0e39\\u0e49\\u0e19\\u0e34\\u0e1e\\u0e19\\u0e18\\u0e4c <br>1. The editor and editorial team must protect the confidentiality of original content of the submitted manuscript, information of the authors and article reviewers to those who not involved in the process before publishing. The information among the authors and reviewers is a double-blinded peer review process. <br>2. \\u0e1a\\u0e23\\u0e23\\u0e13\\u0e32\\u0e18\\u0e34\\u0e01\\u0e32\\u0e23\\u0e41\\u0e25\\u0e30\\u0e01\\u0e2d\\u0e07\\u0e1a\\u0e23\\u0e23\\u0e13\\u0e32\\u0e18\\u0e34\\u0e01\\u0e32\\u0e23 \\u0e1e\\u0e34\\u0e08\\u0e32\\u0e23\\u0e13\\u0e32\\u0e40\\u0e25\\u0e37\\u0e2d\\u0e01\\u0e1c\\u0e39\\u0e49\\u0e1b\\u0e23\\u0e30\\u0e40\\u0e21\\u0e34\\u0e19\\u0e1a\\u0e17\\u0e04\\u0e27\\u0e32\\u0e21\\u0e17\\u0e35\\u0e48\\u0e21\\u0e35\\u0e04\\u0e27\\u0e32\\u0e21\\u0e40\\u0e0a\\u0e35\\u0e48\\u0e22\\u0e27\\u0e0a\\u0e32\\u0e0d\\u0e43\\u0e19\\u0e2a\\u0e32\\u0e02\\u0e32\\u0e17\\u0e35\\u0e48\\u0e40\\u0e01\\u0e35\\u0e48\\u0e22\\u0e27\\u0e02\\u0e49\\u0e2d\\u0e07\\u0e01\\u0e31\\u0e1a\\u0e40\\u0e19\\u0e37\\u0e49\\u0e2d\\u0e2b\\u0e32 \\u0e42\\u0e14\\u0e22\\u0e1c\\u0e39\\u0e49\\u0e1b\\u0e23\\u0e30\\u0e40\\u0e21\\u0e34\\u0e19\\u0e40\\u0e1b\\u0e47\\u0e19\\u0e1c\\u0e39\\u0e49\\u0e17\\u0e35\\u0e48\\u0e21\\u0e35\\u0e08\\u0e23\\u0e34\\u0e22\\u0e18\\u0e23\\u0e23\\u0e21\\u0e41\\u0e25\\u0e30\\u0e17\\u0e31\\u0e28\\u0e19\\u0e04\\u0e15\\u0e34\\u0e17\\u0e35\\u0e48\\u0e14\\u0e35 \\u0e44\\u0e21\\u0e48\\u0e2a\\u0e31\\u0e07\\u0e